  t["Operamos sacando factor común $(k + 1)$: $\\frac{k(k+1)}{2} + (k + 1) = (k + 1)\\left(\\frac{k}{2} + 1\\right) = \\frac{(k+1)(k+2)}{2}$."] = "We work it out by taking out the common factor $(k + 1)$: $\\frac{k(k+1)}{2} + (k + 1) = (k + 1)\\left(\\frac{k}{2} + 1\\right) = \\frac{(k+1)(k+2)}{2}$.";
  t["Operar"] = "Operating";
