  t["¿Cómo comprobarías el resultado sin repetir el mismo cálculo?"] = "How would you check the result without repeating the same calculation?";
  t["¿Cómo se demuestra algo para <em>infinitos</em> casos? No comprobándolos uno a uno, evidentemente. La inducción da una forma de hacerlo en dos pasos."] = "How do you prove something for <em>infinitely many</em> cases? Not by checking them one by one, obviously. Induction gives a way of doing it in two steps.";
  t["¿De qué orden de magnitud es el resultado?"] = "What order of magnitude is the result?";
