  t["¿Qué devuelve este algoritmo? $\\begin{aligned} &s \\leftarrow 1 \\\\ &\\textbf{para } i \\textbf{ desde } 1 \\textbf{ hasta } 3: \\\\ &\\quad s \\leftarrow 2s + i \\\\ &\\textbf{devolver } s \\end{aligned}$"] = "What does this algorithm return? $\\begin{aligned} &s \\leftarrow 1 \\\\ &\\textbf{for } i \\textbf{ from } 1 \\textbf{ to } 3: \\\\ &\\quad s \\leftarrow 2s + i \\\\ &\\textbf{return } s \\end{aligned}$";
